153	///|
154	async fn ensure_ssh_worker(
155	  state : Json,
156	  port : Int32?,
157	  wait_for_git~ : Bool = true,
158	  restart~ : Bool = false,
159	) -> Unit {
160	  let base = adapter_state_home() + "/tunnels"
161	  @fs.mkdir(base, recursive=true, permission=0o700, allow_exist=true)
162	  let directory = match field(state, "tunnelDirectory") {
163	    Some(Json::String(old)) if old.has_prefix(base + "/") && @fs.exists(old) =>
164	      old
165	    _ => {
166	      close_tunnel(state)
167	      let temporary = @fs.tmpdir(prefix="oe")
168	      let name = temporary.split("/").to_array().last().unwrap().to_owned()
169	      @fs.rmdir(temporary)
170	      let directory = base + "/" + name
171	      @fs.mkdir(directory, permission=0o700)
172	      set_field(state, "tunnelDirectory", Json::string(directory))
173	      directory
174	    }
175	  }
176	  let lease = @fs.open(
177	    directory + "/startup.lock",
178	    mode=ReadWrite,
179	    create_mode=OpenOrCreate,
180	    permission=0o600,
181	  )
182	  defer lease.close()
183	  @async.with_timeout(30000, async fn() {
184	    while !lease.try_lock(Exclusive) {
185	      @async.sleep(100)
186	    }
187	  })
188	  if @fs.exists(directory + "/state.json") {
189	    let saved = @json.parse(@fs.read_file(directory + "/state.json").text())
190	    guard field(saved, "workspaceUid") == field(state, "workspaceUid") &&
191	      field(saved, "localPort") ==
192	      port.map(value => Json::number(value.to_double())) else {
193	      raise AdapterError("Tunnel ownership changed")
194	    }
195	    if restart {
196	      restart_tunnel(saved, directory)
197	    }
198	    if worker_alive(directory) {
199	      wait_tunnel(directory, wait_for_git~)
200	      return
201	    }
202	    // A dead supervisor does not invalidate its still-live SSH transport.
203	    // Reuse it so Devsy's old service cleanup cannot remove a new owner's helper.
204	    let reusable = try {
205	      check_tunnel(saved, directory)
206	      true
207	    } catch {
208	      _ => false
209	    }
210	    if reusable {
211	      for name in ["status.json", "git-status"] {
212	        if @fs.exists(directory + "/" + name) {
213	          @fs.remove(directory + "/" + name)
214	        }
215	      }
216	      spawn_tunnel_worker(directory)
217	      wait_tunnel(directory, wait_for_git~)
218	      return
219	    }
220	    stop_tunnel_master(saved, directory)
221	  }
222	  let socket_directory = @fs.tmpdir(prefix="oe")
223	  let saved = Json::empty_object()
224	  for
225	    name in [
226	      "workspaceId", "workspaceUid", "user", "command", "devsyEnv", "home", "context",
227	      "connection",
228	    ] {
229	    if field(state, name) is Some(value) {
230	      set_field(saved, name, value)
231	    }
232	  }
233	  set_field(saved, "socketDirectory", Json::string(socket_directory))
234	  if port is Some(value) {
235	    set_field(saved, "localPort", Json::number(value.to_double()))
236	  }
237	  @fs.write_file(directory + "/state.tmp", saved.stringify(), permission=0o600)
238	  @fs.rename(directory + "/state.tmp", directory + "/state.json", replace=true)
239	  @fs.write_file(directory + "/enabled", "", permission=0o600)
240	  if @fs.exists(directory + "/status.json") {
241	    @fs.remove(directory + "/status.json")
242	  }
243	  spawn_tunnel_worker(directory)
244	  wait_tunnel(directory, wait_for_git~)
245	}
