315	///|
316	async fn reconnect_all_inner(restart~ : Bool = false) -> Unit {
317	  notify(if restart { "restart" } else { "reconnect" })
318	  let base = adapter_state_home() + "/tunnels"
319	  if !@fs.exists(base) {
320	    save_diagnostic("reconnect", "success")
321	    return
322	  }
323	  ignore(saved_proxy_executable())
324	  let mut failures = 0
325	  let permits = @async.Semaphore(4)
326	  @async.with_task_group(async fn(group) {
327	    for name in @fs.readdir(base, sort=true) {
328	      let directory = base + "/" + name
329	      permits.acquire()
330	      group.spawn_bg(async fn() {
331	        defer permits.release()
332	        try {
333	          if @fs.kind(directory, follow_symlink=false) !=
334	            @fs.FileKind::Directory ||
335	            !@fs.exists(directory + "/enabled") {
336	            return
337	          }
338	          let state = @json.parse(
339	            @fs.read_file(directory + "/state.json").text(),
340	          )
341	          validate_state(state)
342	          if worker_alive(directory) {
343	            let current = worker_workspace(state, directory)
344	            guard current is Some(current) &&
345	              field(current, "uid") == field(state, "workspaceUid") else {
346	              @fs.remove(directory + "/enabled")
347	              save_diagnostic("reconnect", "ownership-error")
348	              return
349	            }
350	            if field(current, "running") != Some(Json::boolean(true)) {
351	              save_diagnostic("reconnect", "workspace-stopped")
352	              return
353	            }
354	          }
355	          let port = match field(state, "localPort") {
356	            Some(Json::Number(value, ..)) if value >= 1 &&
357	              value <= 65535 &&
358	              value == value.to_int().to_double() => Some(value.to_int())
359	            None if field(state, "connection") == Some(Json::string("ssh")) =>
360	              None
361	            _ => raise AdapterError("Invalid saved tunnel port")
362	          }
363	          set_field(state, "tunnelDirectory", Json::string(directory))
364	          ensure_ssh_worker(state, port, restart~)
365	          save_diagnostic("reconnect", "success")
366	        } catch {
367	          AdapterError("Tunnel workspace ownership changed") =>
368	            save_diagnostic("reconnect", "ownership-error")
369	          AdapterError("Tunnel workspace stopped") =>
370	            save_diagnostic("reconnect", "workspace-stopped")
371	          _ =>
372	            if @fs.exists(directory) {
373	              failures += 1
374	              save_diagnostic("reconnect", "failed")
375	            } else {
376	              save_diagnostic("reconnect", "target-removed")
377	            }
378	        }
379	      })
380	    }
381	  })
382	  guard failures == 0 else {
383	    raise AdapterError(
384	      "Some tunnels could not be restored; other targets were attempted",
385	    )
386	  }
387	  save_diagnostic("reconnect", "success")
388	}
