431	          raise AdapterError("Tunnel workspace stopped")
432	        }
433	        if field(status, "status") == Some(Json::string("connected")) &&
434	          worker_alive(directory) {
435	          let saved = @json.parse(
436	            @fs.read_file(directory + "/state.json").text(),
437	          )
438	          try {
439	            check_tunnel(saved, directory)
440	            return
441	          } catch {
442	            _ => ()
443	          }
444	        }
445	      }
446	      @async.sleep(100)
447	    }
448	  })
449	  progress_message("ssh-tunnel: connected (" + progress_timing(started) + ")")
450	  guard wait_for_git else { return }
451	  @async.with_timeout(5000, async fn() { wait_git_relay(directory) }) catch {
452	    _ => ()
453	  }
