   145	async fn tunnel_errors(reader : @process.ReadFromProcess) -> String {
   146	  defer reader.close()
   147	  let mut tail = ""
   148	  while reader.read_some(max_len=4096) is Some(bytes) {
   149	    // Decode chunks lossy: arbitrary process stderr need not be valid UTF-8.
   150	    let chunk = @utf8.decode_lossy(bytes)
   151	    tail += chunk
   152	    if tail.length() > 8192 {
   153	      tail = tail[tail.length() - 8192:].to_owned()
   154	    }
   155	  }
   156	  process_error_type(tail)
   157	}
