   415	async fn wait_tunnel(directory : String, wait_for_git~ : Bool = true) -> Unit {
   416	  let started = @env.now()
   417	  progress_message("ssh-tunnel: connecting…")
   418	  errdefer progress_message(
   419	    "ssh-tunnel: failed (" + progress_timing(started) + ")",
   420	  )
   421	  @async.with_timeout(30000, async fn() {
   422	    while true {
   423	      if @fs.exists(directory + "/status.json") {
   424	        let status = @json.parse(
   425	          @fs.read_file(directory + "/status.json").text(),
   426	        )
   427	        if field(status, "status") == Some(Json::string("ownership-error")) {
   428	          raise AdapterError("Tunnel workspace ownership changed")
   429	        }
   430	        if field(status, "status") == Some(Json::string("workspace-stopped")) {
   431	          raise AdapterError("Tunnel workspace stopped")
   432	        }
   433	        if field(status, "status") == Some(Json::string("connected")) &&
   434	          worker_alive(directory) {
   435	          let saved = @json.parse(
   436	            @fs.read_file(directory + "/state.json").text(),
   437	          )
   438	          try {
   439	            check_tunnel(saved, directory)
   440	            return
   441	          } catch {
   442	            _ => ()
   443	          }
   444	        }
   445	      }
   446	      @async.sleep(100)
   447	    }
   448	  })
   449	  progress_message("ssh-tunnel: connected (" + progress_timing(started) + ")")
   450	  guard wait_for_git else { return }
   451	  @async.with_timeout(5000, async fn() { wait_git_relay(directory) }) catch {
   452	    _ => ()
   453	  }
   454	  let git_status = if @fs.exists(directory + "/git-status") {
   455	    @fs.read_file(directory + "/git-status").text()
   456	  } else {
   457	    "pending"
   458	  }
   459	  if git_status != "ready" && git_status != "disabled" {
   460	    @stdio.stderr.write(
   461	      "orca-env-devsy: Git credential relay readiness is unavailable; Orca remains connected. Inspect local git-relay diagnostics.\n",
   462	    ) catch {
   463	      _ => ()
   464	    }
   465	    save_diagnostic("git-relay", "warning", error_type="readiness_unavailable")
   466	  }
   467	}
