    93	fn process_error_type(output : String) -> String {
    94	  let text = output.to_lower()
    95	  if text.contains("out of memory") || text.contains("cannot allocate memory") {
    96	    "memory_exhausted"
    97	  } else if text.contains("no space left on device") {
    98	    "disk_exhausted"
    99	  } else if text.contains("address already in use") ||
   100	    text.contains("addrinuse") {
   101	    "address_in_use"
   102	  } else if text.contains("permission denied (publickey") ||
   103	    text.contains("authentication failed") {
   104	    "authentication_failed"
   105	  } else if text.contains("host key verification failed") {
   106	    "host_key_failed"
   107	  } else if text.contains("connection refused") {
   108	    "connection_refused"
   109	  } else if text.contains("connection timed out") ||
   110	    text.contains("operation timed out") {
   111	    "connection_timeout"
   112	  } else if text.contains("could not resolve hostname") {
   113	    "name_resolution"
   114	  } else if text.contains("controlsocket") || text.contains("control socket") {
   115	    "control_socket"
   116	  } else if text.contains("build_vm:") {
   117	    "vm_boot"
   118	  } else if text.contains("create microsandbox vm") && text.contains("network:") {
   119	    "vm_network"
   120	  } else if text.contains("create microsandbox vm") && text.contains("mount:") {
