   754	async fn check_tunnel(state : Json, directory : String) -> Unit {
   755	  @async.with_timeout(2000, async fn() {
   756	    let (status, _, _) = @process.collect_output(
   757	      "ssh",
   758	      ssh_args(state) + ["-S", control_socket(state, directory), "-O", "check"],
   759	    )
   760	    guard status == 0 else { raise AdapterError("Tunnel not ready") }
   761	    match field(state, "localPort") {
   762	      Some(Json::Number(value, ..)) => {
   763	        let socket = @socket.Tcp::connect(
   764	          @socket.Addr::parse("127.0.0.1:" + value.to_int().to_string()),
   765	        )
   766	        socket.close()
   767	      }
   768	      None if field(state, "connection") == Some(Json::string("ssh")) => ()
   769	      _ => raise AdapterError("Missing tunnel port")
   770	    }
   771	  })
   772	}
